// pybytes.mjs
// Minimal emulation of Python's `bytes` object.
// A byte string is stored as a latin1 (binary) JS string: one char per byte,
// so byte value i is latin1.charCodeAt(i). This keeps all Bencode payloads
// (which are pure byte sequences) exact without any external dependency.

export class UnicodeEncodeError extends Error {
  constructor(encoding, offending, position, endPosition) {
    super(buildMessage(encoding, offending, position, endPosition));
    this.name = 'UnicodeEncodeError';
  }
}

// Escape a character the way Python does inside a UnicodeEncodeError message.
function escapeChar(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

function buildMessage(encoding, offending, position, endPosition) {
  const chars = [...offending].map((ch) => escapeChar(ch.codePointAt(0))).join('');
  if (endPosition - position === 1) {
    return `'${encoding}' codec can't encode character '${chars}' in position ${position}: ordinal not in range(128)`;
  }
  return `'${encoding}' codec can't encode characters '${chars}' in position ${position}-${endPosition - 1}: ordinal not in range(128)`;
}

export class PyBytes {
  constructor(latin1) {
    this.latin1 = latin1;
  }

  get length() {
    return this.latin1.length;
  }

  byteAt(i) {
    return this.latin1.charCodeAt(i);
  }

  // Equivalent of Python str.encode('ascii'): raises UnicodeEncodeError on
  // the first maximal run of non-ASCII characters, exactly like CPython.
  static fromAscii(str) {
    let i = 0;
    const cps = [...str]; // iterate by code point, like Python
    while (i < cps.length) {
      if (cps[i].codePointAt(0) > 0x7f) {
        let j = i;
        while (j < cps.length && cps[j].codePointAt(0) > 0x7f) j++;
        throw new UnicodeEncodeError('ascii', cps.slice(i, j).join(''), i, j);
      }
      i++;
    }
    return new PyBytes(str);
  }

  // Equivalent of Python repr(bytes), e.g. b'l4:utf8i65535eli65535eee'
  repr() {
    let out = "b'";
    for (let i = 0; i < this.latin1.length; i++) {
      const c = this.latin1.charCodeAt(i);
      if (c === 0x5c) out += '\\\\'; // backslash
      else if (c === 0x27) out += "\\'"; // single quote
      else if (c === 0x09) out += '\\t';
      else if (c === 0x0a) out += '\\n';
      else if (c === 0x0d) out += '\\r';
      else if (c >= 0x20 && c < 0x7f) out += this.latin1[i];
      else out += '\\x' + c.toString(16).padStart(2, '0');
    }
    return out + "'";
  }

  toString() {
    return this.repr();
  }
}

// pyrepr.mjs
// Python-style repr()/print() rendering for the value kinds this project uses:
// bytes (PyBytes), ints (BigInt/Number) and nested lists (Array).

import { PyBytes } from './pybytes.mjs';

export function pyRepr(value) {
  if (value instanceof PyBytes) return value.repr();
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return String(value);
  if (typeof value === 'string') return pyStrRepr(value);
  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
  throw new TypeError(`pyRepr: unsupported value of type ${typeof value}`);
}

// repr() of a Python str: prefer single quotes, switch to double quotes only
// when the string contains a single quote and no double quote.
export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else out += ch;
  }
  return out + quote;
}

// bencoder.mjs
// Pure-JS reimplementation of the Python `bencoder` package's encode/decode
// for the data model used here: byte strings (PyBytes), integers and lists.
// Wire format (Bencode):
//   bytes  -> <len>:<raw bytes>
//   int    -> i<integer>e
//   list   -> l<item1><item2>...e
// All payloads are carried as latin1 strings inside PyBytes (one char = one byte).

import { PyBytes } from './pybytes.mjs';

export function encode(value) {
  if (value instanceof PyBytes) {
    return new PyBytes(value.length + ':' + value.latin1);
  }
  if (typeof value === 'bigint' || typeof value === 'number') {
    return new PyBytes('i' + value.toString() + 'e');
  }
  if (Array.isArray(value)) {
    let body = '';
    for (const item of value) body += encode(item).latin1;
    return new PyBytes('l' + body + 'e');
  }
  throw new TypeError(`bencode: cannot encode value of type ${typeof value}`);
}

export function decode(data) {
  const s = data instanceof PyBytes ? data.latin1 : data;
  const [value, pos] = decodeAt(s, 0);
  if (pos !== s.length) {
    throw new Error(`bencode: trailing data at position ${pos}`);
  }
  return value;
}

function decodeAt(s, i) {
  const c = s[i];
  if (c === 'i') {
    const end = s.indexOf('e', i);
    if (end === -1) throw new Error('bencode: unterminated integer');
    return [BigInt(s.slice(i + 1, end)), end + 1];
  }
  if (c === 'l') {
    const items = [];
    let p = i + 1;
    while (p < s.length && s[p] !== 'e') {
      const [v, np] = decodeAt(s, p);
      items.push(v);
      p = np;
    }
    if (p >= s.length) throw new Error('bencode: unterminated list');
    return [items, p + 1];
  }
  if (c >= '0' && c <= '9') {
    const colon = s.indexOf(':', i);
    if (colon === -1) throw new Error('bencode: malformed byte string length');
    const len = Number(s.slice(i, colon));
    const start = colon + 1;
    return [new PyBytes(s.slice(start, start + len)), start + len];
  }
  throw new Error(`bencode: invalid token at position ${i}`);
}

// argparse.mjs
// Minimal reimplementation of the subset of Python's argparse used by the
// original script: required long options with type str/int, `-h/--help`,
// `--opt value` and `--opt=value` forms, and argparse-identical
// usage/error/help text with matching exit codes (0 for help, 2 for errors).

import { pyStrRepr } from './pyrepr.mjs';

// Emulates Python's int(str): trims surrounding whitespace, accepts an
// optional sign and decimal digits with single underscores between digits.
function parsePythonInt(raw) {
  const t = raw.trim();
  if (/^[+-]?\d+(_\d+)*$/.test(t)) return BigInt(t.replace(/_/g, ''));
  return null;
}

// argparse treats a token that looks like a negative number as a value
// (this parser has no options that look like negative numbers).
function looksLikeOption(token) {
  if (!token.startsWith('-') || token === '-') return false;
  return !/^-\d/.test(token) && !/^-\.\d/.test(token);
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.options = []; // { flag, dest, metavar, required, type }
  }

  addArgument(flag, { required = false, type = 'str' } = {}) {
    const dest = flag.replace(/^--?/, '');
    this.options.push({ flag, dest, metavar: dest.toUpperCase(), required, type });
  }

  usage() {
    const parts = this.options.map((o) => (o.required ? `${o.flag} ${o.metavar}` : `[${o.flag} ${o.metavar}]`));
    return `usage: ${this.prog} [-h]${parts.length ? ' ' + parts.join(' ') : ''}`;
  }

  printHelp() {
    const lines = [this.usage(), '', 'options:', '  -h, --help  show this help message and exit'];
    for (const o of this.options) lines.push(`  ${o.flag} ${o.metavar}`);
    console.log(lines.join('\n'));
  }

  error(message) {
    console.error(this.usage());
    console.error(`${this.prog}: error: ${message}`);
    process.exit(2);
  }

  parseArgs(argv) {
    const values = {};
    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      let token = argv[i];

      if (token === '-h' || token === '--help') {
        this.printHelp();
        process.exit(0);
      }

      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }

      const opt = this.options.find((o) => o.flag === token);
      if (!opt) {
        extras.push(argv[i]);
        continue;
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
      } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
        raw = argv[++i];
      } else {
        this.error(`argument ${opt.flag}: expected one argument`);
      }

      if (opt.type === 'int') {
        const parsed = parsePythonInt(raw);
        if (parsed === null) {
          this.error(`argument ${opt.flag}: invalid int value: ${pyStrRepr(raw)}`);
        }
        values[opt.dest] = parsed;
      } else {
        values[opt.dest] = raw;
      }
      seen.add(opt.dest);
    }

    const missing = this.options.filter((o) => o.required && !seen.has(o.dest));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.map((o) => o.flag).join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}

